// 2. 分片路由示例
@Service
public class OrderService {
    @Autowired
    private OrderMapper orderMapper; // ShardingSphere代理

    public OrderDTO getOrder(Long orderId, Long userId) {
        // ShardingSphere根据user_id自动路由到正确的库
        // 根据order_id自动路由到正确的表
        return orderMapper.selectByOrderIdAndUserId(orderId, userId);
    }

    // 跨库查询需要全库扫描（性能差，避免）
    public List<OrderDTO> searchOrders(OrderQuery query) {
        // 如果查询条件没有分片键，会全库扫描
        return orderMapper.selectByCondition(query);
    }
}

// 3. 全局ID - 雪花算法
public class OrderIdGenerator {
    private final SnowflakeIdGenerator snowflake;

    public Long generate() {
        return snowflake.nextId();
    }
}

// 4. 分片键设计
// 好的分片键：user_id（查询频繁，分布均匀）
// 差的分片键：create_time（数据倾斜，热点）

// 查询必须带分片键
// ✅ SELECT * FROM order WHERE user_id = 123
// ❌ SELECT * FROM order WHERE order_id = 456 (全库扫描)

// 5. 双写迁移方案
@Service
public class DualWriteMigration {
    @Autowired
    @Qualifier("oldDataSource")
    private JdbcTemplate oldDb;

    @Autowired
    @Qualifier("newDataSource")
    private JdbcTemplate newDb;

    @Transactional
    public void createOrder(Order order) {
        // 双写
        oldDb.update("INSERT INTO order...", order);
        newDb.update("INSERT INTO order...", order);
    }
}
